    private static BigDecimal parsePercent(String percent) {
        BigDecimal rate;
        try {
            rate = new BigDecimal(percent.trim());
        } catch (NullPointerException | NumberFormatException e) {
            throw new ShopProblem("INVALID_DISCOUNT", "Discount must be a number, got: " + percent);
        }
        if (rate.signum() < 0 || rate.compareTo(HUNDRED) > 0) {
            throw new ShopProblem("INVALID_DISCOUNT", "Discount must be between 0 and 100 percent, got: " + percent);
        }
        return rate;
    }

